/* Keeps Rust std/core internals out of libobs's dynamic symbol table, so
 * ENABLE_RUST_LIBOBS=ON exports exactly what the C build exports. The C ABI
 * shims are #[no_mangle] and stay global. libobs exports no C++ symbols. */
{
  local:
    _ZN*;
    _R*;
    rust_eh_personality;
    /* Rust state for base.c. The variadic entry points stay in
     * util/base-variadic.c and keep the public names blog/blogva/bcrash. */
    base_begin_crash;
    base_default_log_handler;
    /* profiler.c's variadic profile_store_name stays in
     * util/profiler-variadic.c and pushes through this. */
    profiler_name_store_push;
    base_log_literal;
    /* utf8.c is not exported by the C libobs, so its Rust shims are hidden
     * too (listed in rust-hidden.txt). */
    utf8_to_wchar;
    wchar_to_utf8;
    /* platform-nix.c. obs-module.c calls it; the C build does not export it. */
    get_plugin_info;
    /* obs-hotkey-name-map.c. Declared in obs-internal.h; obs.c calls it on
     * shutdown. Not EXPORT. */
    obs_hotkey_name_map_free;
    /* platform-windows.c. Not EXPORT. */
    get_win_release_id;
    DllMain;
    /* video-io.c. Not EXPORT; callers are inside libobs. */
    video_output_inc_texture_encoders;
    video_output_dec_texture_encoders;
    video_output_inc_texture_frames;
    video_output_inc_texture_skipped_frames;
    video_output_create_with_frame_rate_divisor;
    video_output_free_frame_rate_divisor;
    /* obs-data.c: json_decref is a static inline. The glue is not EXPORT. */
    obs_data_json_decref;
    /* obs-scene-bounds.c. obs-scene.c calls it inside libobs. Not EXPORT. */
    obs_bounds_fit_scale;
    /* pulseaudio-stream-flags.c. pulseaudio-output.c calls them inside
     * libobs. Not EXPORT. */
    pulseaudio_monitor_stream_flags;
    pulseaudio_monitor_reset_on_sink_event;
    pulseaudio_monitor_backlog_excess;
};
